INSERT INTO wastewater (water_id,site_id,stream,stage,flow,flow_unit,flow_basis,pollutants,process,destination,residuals,source_id,confidence,notes) VALUES ('W029-01','CN0194','全厂共享综合污水站（既有组成表）','2024环评回顾已建',80,'m³/d','设施处理能力','含油、工艺水、冲洗水及初雨','三效蒸发→缓冲→破乳→絮凝调节→沉淀→EGSB→A/O→MBR','园区污水厂→谭湖沟→天门河','生化污泥和隔油池废油危废','S029-01','WEB_PRIMARY','同报告依托分析又列不同流程；非催化剂专线，不确认MBR当前运行，能力不得重复加总');
INSERT INTO wastewater (water_id,site_id,stream,stage,flow,flow_unit,flow_basis,pollutants,process,destination,residuals,source_id,confidence,notes) VALUES ('W029-02','CN0194','全厂共享站（依托分析异文）','2024环评依托分析，现有表述',80,'m³/d','同一站处理能力','含油等','格栅→调节→隔油→二级气浮→水解酸化→二级好氧→沉淀→双级过滤','园区污水厂→谭湖沟','污泥及油危废','S029-01','WEB_PRIMARY','同一报告p68–69与既有组成表冲突；不是第二座80m³/d站；未说明哪一套在运行');
