INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N029-01','CN0194','S029-01','催化剂装置状态纠正及工艺冲突','表2.2-2、2.2-3、2.2-4；p30–32与p68–69','报告二期装置已建成验收、设计20000t/a，原首次公示未建旧口径保留；三期丁二酸酐不再建设。共享站450m²/80m³/d，两处分别描述三效+EGSB/AO/MBR和格栅隔油二级气浮水解二级好氧双级过滤，保留冲突，不叠加容量、不确认MBR实际在用。雨水/事故废水收集系统3040m³（292、48及2×1350m³），脱盐水制备8m³/h不是废水能力；一期废油危废污泥及隔油废油分别委外。截图404。','WEB_PRIMARY','公开文本摘录；未归档原件','2026-11-27');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N029-02','CN0194','S029-02','后续现场证据边界','报道正文','2026-01报道废旧润滑油加工现场，并称企业经营环保催化剂；未给二期实际产量、催化剂独立水量及站当前设备，不据此解除MBR冲突。','WEB_SECONDARY','公开文本摘录；未归档原件','2026-11-27');
