INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('A029-01','R029-01','CN0194','shared_station_conflicting_versions','screening',1,'分质回用和处理减量','先查实际设备版本；有MBR则核维护、出水及深度回用；没有则比较气浮生化后UF/RO，含油水需先除油，浓水须闭合','conditional','实际水量、水质、合规浓水去向与运行边界须核；不把候选当实装','同一报告两种不同描述，图为并列证据版本、并非实际平行两套处理线；共有80m³/d；膜不确定','INFERRED工程候选；未验证运行与费用','现场设备、油、TDS、COD、膜、实际流量、回用水质','核验收及台账、分质采样、除油/膜污染试验、成本对比','维护原有物化生化及分流',NULL,NULL,NULL,NULL,NULL,NULL,'无实测和完整运行边界，六维不赋值','2026-11-27');
