INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N029-03','CN0066','S029-03','历史经济性估算','第7.1、7.2节 p171','2018环评改扩建废水成本约5.5元/t、年5万元，回用水预计节约约3万元（原文未给核算水价）；总环保75万元、按15年折算5万元/年，废气固废费用20万元/年均非废水专属。不可用作2026 240m³/d站运行单价。封面脱硫/说明脱硝异文保留；截图超时。','WEB_PRIMARY','公开文本摘录；未归档原件','2026-11-27');
